      const loaded = yield* store.load;
      assert.strictEqual(loaded.defaultLocale, "en");
      assert.deepStrictEqual(
        loaded.people.map((person) => [person.locale, person.detectedLocale]),
        [[null, null]],
      );
    }),
  );
});

